SELECT p.*, pm.role AS my_role, (SELECT COUNT(*) FROM sa_project_member c WHERE c.project_id=p.id AND c.status='ACTIVE') AS member_count
FROM sa_project p JOIN sa_project_member pm ON pm.project_id=p.id AND pm.user_id=#{userId} AND pm.status='ACTIVE'
WHERE p.id=#{projectId}

SELECT p.*,pm.role AS my_role,(SELECT COUNT(*) FROM sa_project_member c WHERE c.project_id=p.id AND c.status='ACTIVE') AS member_count
FROM sa_project p JOIN sa_project_member pm ON pm.project_id=p.id AND pm.user_id=#{userId} AND pm.status='ACTIVE'
WHERE 1=1  ORDER BY p.update_time DESC,p.id DESC LIMIT #{offset},#{query.pageSize}

SELECT pm.id,pm.project_id,pm.user_id,u.username,u.nickname,pm.role,pm.status,pm.joined_at,pm.removed_at,pm.update_time
FROM sa_project_member pm JOIN sa_user u ON u.id=pm.user_id
WHERE pm.project_id=#{projectId} AND pm.status='ACTIVE'
AND (u.username LIKE CONCAT('%',#{query.keyword},'%') OR u.nickname LIKE CONCAT('%',#{query.keyword},'%'))
AND pm.role=#{query.role}
ORDER BY FIELD(pm.role,'OWNER','MAINTAINER','LEARNER'),pm.joined_at,pm.user_id LIMIT #{offset},#{query.pageSize}
